head.script:
// 콘솔 오류 수집 (엔진이 내부에서 catch 한 오류는 window.onerror 로 잡히지 않으므로 console.error 를 감싸서 수집)
scwin.errList = [];

scwin.onpageload = function () {
    let orgError = console.error;
    console.error = function () {
        let msg = [];
        for (let i = 0; i < arguments.length; i++) {
            let arg = arguments[i];
            if (arg && arg.message) {
                msg.push((arg.name ? arg.name + ": " : "") + arg.message.split("\n")[0]);
            } else if (typeof arg === "string") {
                msg.push(arg.split("\n")[0]);
            }
        }
        scwin.errList.push(msg.join(" "));
        return orgError.apply(console, arguments);
    };
};

// Cell 더블클릭(편집 진입) 후 직전 출력 이후 발생한 콘솔 오류 건수 출력
//  - 오류는 oncelldblclick 보다 먼저 출력되므로 직전 출력 시점부터 누적된 건수로 판정
scwin.lastIdx = 0;
scwin.grd_target_oncelldblclick = function (row, col) {
    let colId = grd_target.getColumnID(col);
    setTimeout(function () {
        let list = scwin.errList.slice(scwin.lastIdx);
        scwin.lastIdx = scwin.errList.length;
        let cnt = list.length;
        let str = "[" + colId + " Cell 더블클릭] 기대 : 오류 0건  /  실제 : 오류 " + cnt + "건  → " + (cnt === 0 ? "PASS" : "FAIL");
        if (cnt > 0) {
            str += "\n    " + list[0];
        }
        scwin.setReturnValue(str);
    }, 300);
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
